<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {apiError} from './apiError';
defineProps<{disabled:boolean}>();const emit=defineEmits<{apply:[csv:string,source:any]}>();const catalog=ref<any>(null);const selected=ref('');const unit=ref('');const preview=ref<any>(null);const error=ref('');const loading=ref(false);let request=0;
watch([selected,unit],()=>{preview.value=null;request++});
onMounted(async()=>{try{const r=await fetch('/api/alashankou');if(!r.ok)throw Error('资料目录读取失败');catalog.value=await r.json()}catch(e){error.value=String(e)}});
async function inspect(){const id=++request;loading.value=true;preview.value=null;error.value='';try{const r=await fetch('/api/alashankou/'+selected.value+'/preview?unit='+(unit.value||'MW'));const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));if(id===request)preview.value=d}catch(e){if(id===request)error.value=String(e)}finally{if(id===request)loading.value=false;else loading.value=false}}
</script>
<template><article><h3>SourceData · 阿拉山口资料接入</h3><p v-if="error" class="error">{{error}}</p><template v-if="catalog"><p v-for="note in catalog.notes">{{note}}</p><div class="actions"><select v-model="selected" :disabled="disabled"><option value="">选择负荷或风场资料</option><option v-for="f in catalog.files.filter((f:any)=>f.kind!=='reference')" :value="f.id">{{f.name}}</option></select><select v-model="unit" :disabled="disabled"><option value="">核实并选择负荷原始单位</option><option value="MW">原始值按MW（乘1000）</option><option value="kW">原始值按kW</option></select><button @click="inspect" :disabled="disabled||!selected||loading">{{loading?'读取中':'预览资料'}}</button></div><template v-if="preview?.kind==='load'"><p>{{preview.source_import.method}}</p><p>所选原始单位：{{preview.source_import.unit_assumption}}，转换后24小时，最大负荷 {{Math.max(...preview.rows.map((r:any)=>r.load_kw)).toFixed(2)}} kW。原表未注明单位，请核实后应用。</p><div class="scroll"><table><tr><th>时间</th><th>负荷 / kW</th><th>风电 / kW</th><th>光伏 / kW</th></tr><tr v-for="r in preview.rows"><td>{{r.timestamp}}</td><td>{{r.load_kw.toFixed(2)}}</td><td>{{r.wind_kw}}</td><td>{{r.pv_kw}}</td></tr></table></div><button :disabled="disabled||!unit" @click="emit('apply',preview.csv,preview.source_import)">应用到当前工程源荷</button></template><template v-if="preview?.kind==='wind_monthly'"><p>{{preview.note}}</p><div class="scroll"><table><tr v-for="r in preview.rows"><td v-for="(v,k) in r">{{v}}</td></tr></table></div></template><details><summary>原始资料与图纸下载（{{catalog.files.length}}项）</summary><p v-for="f in catalog.files"><a :href="'/api/alashankou/'+f.id+'/file'" target="_blank" rel="noopener">{{f.name}}</a> · {{f.kind==='load'?'典型日负荷':f.kind==='wind_monthly'?'月发电量':'参考资料'}}</p></details></template></article></template>
<style scoped>select{padding:8px;max-width:100%}.scroll{max-height:300px;overflow:auto;margin:16px 0}details{margin-top:20px}summary{cursor:pointer}</style>
